import { useEffect, useState, memo } from "react";
import ReactDOM from "react-dom";

/**
 * @description 자식 요소를 Shadow DOM에 렌더링하는 최적화된 컴포넌트
 */
export const ShadowWrapper = memo(
  ({ children, css, tagName }: { children: React.ReactNode; css?: string; tagName: "input" }) => {
    const [host, setHost] = useState<HTMLDivElement | null>(null);
    const [shadowRoot, setShadowRoot] = useState<ShadowRoot | null>(null);
    const Component = tagName;

    useEffect(() => {
      if (host && !shadowRoot) {
        const shadow = host.attachShadow({ mode: "open" });
        setShadowRoot(shadow);
      }
    }, [host, shadowRoot]);

    return (
      <Component ref={setHost}>
        {shadowRoot &&
          ReactDOM.createPortal(
            <>
              {css && <style>{css}</style>}
              {children}
            </>,
            shadowRoot,
          )}
      </Component>
    );
  }
);
ShadowWrapper.displayName = "ShadowWrapper";

